scripts.args_schema:
{
  "type": "object",
  "properties": {
    "queries": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 200
      },
      "minItems": 1,
      "maxItems": 3,
      "description": "AI 根据课题构建的三组英文关键词，依次为技术＋业务、业务＋系统类型、技术＋系统类型。"
    },
    "rows": {
      "type": "integer",
      "minimum": 1,
      "maximum": 20,
      "description": "每组候选数，默认 10。"
    },
    "offset": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "同组查询分页偏移，默认 0。"
    },
    "type": {
      "type": "string",
      "enum": [
        "journal-article",
        "proceedings-article"
      ],
      "description": "默认 journal-article；不足时可补充会议论文。"
    },
    "fromYear": {
      "type": "integer",
      "minimum": 1000,
      "maximum": 9999,
      "description": "可选，起始出版年。"
    },
    "untilYear": {
      "type": "integer",
      "minimum": 1000,
      "maximum": 9999,
      "description": "可选，截止出版年。"
    }
  },
  "required": [
    "queries"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "doi": {
      "type": "string",
      "description": "从检索结果中选出的真实 DOI。"
    },
    "index": {
      "type": "integer",
      "minimum": 1,
      "maximum": 100,
      "description": "按相关性排序后的连续引文编号。"
    }
  },
  "required": [
    "doi",
    "index"
  ],
  "additionalProperties": false
}
